package prak7.christian.jonathan.laimena;

import java.awt.*;
import java.util.ArrayList;
import javax.swing.*;

public class App {
    private static ArrayList<User> userList = new ArrayList<>();

    public static void main(String[] args) {
        JFrame frame = new JFrame("Contoh Aplikasi GUI Sederhana");

        // CardLayout untuk berpindah antar halaman
        CardLayout cardLayout = new CardLayout();
        JPanel mainPanel = new JPanel(cardLayout);

        // Inisialisasi masing-masing Halaman
        HelloPage helloPage = new HelloPage(cardLayout, mainPanel);
        LoginPage loginPage = new LoginPage(cardLayout, mainPanel, userList, helloPage);
        RegisterPage registerPage = new RegisterPage(cardLayout, mainPanel, userList);

        // Daftarkan halaman ke CardLayout
        mainPanel.add(loginPage, "Login");
        mainPanel.add(registerPage, "Register");
        mainPanel.add(helloPage, "Hello");

        // Konfigurasi Window Utama
        frame.add(mainPanel);
        frame.setSize(450, 350);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setLocationRelativeTo(null); // Posisi tengah layar
        frame.setVisible(true); // Tampilkan ke layar
    }
}